  SELECT domain.id32(e.id), max(s.block_number), domain.to_string((array_agg(s.value) FILTER (WHERE c.id = '\xfdbdfda9d0933af67d5682f368771753d17c0fef55c57d62a98476dd75090580'))[1]) AS description,
