CREATE OR REPLACE PROCEDURE domain.bootstrap() LANGUAGE plpgsql AS $$
BEGIN
  -- typed entities: EntityType names the kind; every column decoded from the current value of its component
  INSERT INTO domain.entity (id, kind, recognised_by, created_block, updated_block)
  SELECT domain.id32(e.id), domain.to_string(s.value), 'bootstrap', s.block_number, s.block_number
  FROM ecs.state s JOIN ecs.entities e ON e.idx = s.entity_idx JOIN ecs.components c ON c.idx = s.component_idx
  WHERE c.id = '\x5d88ced8d8e079072bf73f49fc87661b519c50d79482941abb852ba2b10909cd' AND NOT s.removed AND domain.to_string(s.value) IN (SELECT name FROM domain.kind WHERE kind = 'entity')
  ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, updated_block = GREATEST(domain.entity.updated_block, EXCLUDED.updated_block);
  PERFORM domain.refresh_account(ARRAY(SELECT id FROM domain.entity WHERE kind = 'ACCOUNT'));
  PERFORM domain.refresh_equipment(ARRAY(SELECT id FROM domain.entity WHERE kind = 'EQUIPMENT'));
  PERFORM domain.refresh_friendship(ARRAY(SELECT id FROM domain.entity WHERE kind = 'FRIENDSHIP'));
  PERFORM domain.refresh_harvest(ARRAY(SELECT id FROM domain.entity WHERE kind = 'HARVEST'));
  PERFORM domain.refresh_inventory(ARRAY(SELECT id FROM domain.entity WHERE kind = 'INVENTORY'));
  PERFORM domain.refresh_kami(ARRAY(SELECT id FROM domain.entity WHERE kind = 'KAMI'));
  PERFORM domain.refresh_kami_collection_offer(ARRAY(SELECT id FROM domain.entity WHERE kind = 'KAMI_COLLECTION_OFFER'));
  PERFORM domain.refresh_kami_listing(ARRAY(SELECT id FROM domain.entity WHERE kind = 'KAMI_LISTING'));
  PERFORM domain.refresh_kami_offer(ARRAY(SELECT id FROM domain.entity WHERE kind = 'KAMI_OFFER'));
  PERFORM domain.refresh_pool_share(ARRAY(SELECT id FROM domain.entity WHERE kind = 'POOL_SHARE'));
  PERFORM domain.refresh_tax(ARRAY(SELECT id FROM domain.entity WHERE kind = 'TAX'));
  PERFORM domain.refresh_token_receipt(ARRAY(SELECT id FROM domain.entity WHERE kind = 'TOKEN_RECEIPT'));
  PERFORM domain.refresh_trade(ARRAY(SELECT id FROM domain.entity WHERE kind = 'TRADE'));
  PERFORM domain.refresh_quest(ARRAY(SELECT id FROM domain.entity WHERE kind = 'QUEST'));
  PERFORM domain.refresh_relationship(ARRAY(SELECT id FROM domain.entity WHERE kind = 'RELATIONSHIP'));
  PERFORM domain.refresh_skill(ARRAY(SELECT id FROM domain.entity WHERE kind = 'SKILL'));
  PERFORM domain.refresh_allocation(ARRAY(SELECT id FROM domain.entity WHERE kind = 'ALLOCATION'));
  PERFORM domain.refresh_auction(ARRAY(SELECT id FROM domain.entity WHERE kind = 'AUCTION'));
  PERFORM domain.refresh_bonus(ARRAY(SELECT id FROM domain.entity WHERE kind = 'BONUS'));
  PERFORM domain.refresh_faction(ARRAY(SELECT id FROM domain.entity WHERE kind = 'FACTION'));
  PERFORM domain.refresh_goal(ARRAY(SELECT id FROM domain.entity WHERE kind = 'GOAL'));
  PERFORM domain.refresh_item(ARRAY(SELECT id FROM domain.entity WHERE kind = 'ITEM'));
  PERFORM domain.refresh_listing(ARRAY(SELECT id FROM domain.entity WHERE kind = 'LISTING'));
  PERFORM domain.refresh_node(ARRAY(SELECT id FROM domain.entity WHERE kind = 'NODE'));
  PERFORM domain.refresh_npc(ARRAY(SELECT id FROM domain.entity WHERE kind = 'NPC'));
  PERFORM domain.refresh_pool(ARRAY(SELECT id FROM domain.entity WHERE kind = 'POOL'));
  PERFORM domain.refresh_recipe(ARRAY(SELECT id FROM domain.entity WHERE kind = 'RECIPE'));
  PERFORM domain.refresh_reference(ARRAY(SELECT id FROM domain.entity WHERE kind = 'REFERENCE'));
  PERFORM domain.refresh_room(ARRAY(SELECT id FROM domain.entity WHERE kind = 'ROOM'));
  PERFORM domain.refresh_scavenge(ARRAY(SELECT id FROM domain.entity WHERE kind = 'SCAVENGE'));
  PERFORM domain.refresh_trait(ARRAY(SELECT id FROM domain.entity WHERE kind = 'TRAIT'));
END $$;
-- +goose StatementEnd

